// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/21-screen-time.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useEffect, useState } from 'react';
import { Bell, Clock4, LayoutDashboard, Settings, ShieldCheck, Timer, TrendingUp } from 'lucide-react';
import { CoverFill } from '~/components/shared/CoverFill';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import { post, put } from '~/services/httpMethods';
import { unwrapData } from '~/utils/unwrapData';
import '~/styles/protos/screen-time.css';

const bn = (value: number) => new Intl.NumberFormat('bn-BD').format(value);
const USED_MINUTES = 24;

export default function ScreenTimePage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery("GET /api/parent/students/:id/screen-time");
  const ledger = unwrapData<{ studentId?: string; limitMinutes?: number }>(data);
  const studentId = ledger?.studentId;

  const [limit, setLimit] = useState(60);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [extended, setExtended] = useState(false);

  useEffect(() => {
    if (typeof ledger?.limitMinutes === 'number') setLimit(ledger.limitMinutes);
  }, [ledger?.limitMinutes]);

  const saveLimit = async (next: number) => {
    const previous = limit;
    setLimit(next);
    setNotice(null);
    if (!studentId) return;
    setSaving(true);
    try {
      await put(`/parent/students/${studentId}/screen-time`, { limitMinutes: next });
      setNotice('সীমা আপডেট হয়েছে');
    } catch {
      setLimit(previous);
      setNotice('সীমা সেভ হয়নি। আবার চেষ্টা করো।');
    } finally {
      setSaving(false);
    }
  };

  const extend = async () => {
    if (!studentId || extended) return;
    setSaving(true);
    try {
      await post(`/parent/students/${studentId}/screen-time/extend`, { minutes: 15 });
      setLimit((current) => current + 15);
      setExtended(true);
      setNotice('আজকের জন্য ১৫ মিনিট বাড়ানো হয়েছে');
    } catch {
      setNotice('সময় বাড়ানো যায়নি। আবার চেষ্টা করো।');
    } finally {
      setSaving(false);
    }
  };

  const remaining = Math.max(0, limit - USED_MINUTES);
  const blocked = limit > 0 && USED_MINUTES >= limit;
  const statusLabel = limit === 0 ? 'সীমা নেই' : blocked ? 'সীমা শেষ' : 'সীমার মধ্যে';
  const barPercent = limit === 0 ? 0 : Math.min(100, Math.round((USED_MINUTES / limit) * 100));
  const presets: Array<{ value: number; label: string; testId: string }> = [
    { value: 30, label: '৩০ মিনিট', testId: 'st-preset-30' },
    { value: 60, label: '৬০ মিনিট', testId: 'st-preset-60' },
    { value: 90, label: '৯০ মিনিট', testId: 'st-preset-90' },
    { value: 0, label: 'কোনো সীমা নেই', testId: 'st-preset-none' },
  ];

  return (
    <div data-testid="screen-time-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <header className="ksr-appbar" >
          <span className="ksr-wordmark" data-testid="appbar-brand">স্মার্টবিদ্যা</span>
          <span className="ksr-appbar-title" data-slot="title" data-testid="sub-title"></span>
          <div className="row" style={{ marginLeft: 'auto' }}>
            <button className="ksr-round" type="button" style={{ position: 'relative' }} data-testid="appbar-notifications" aria-label="নোটিফিকেশন — 3 টি না পড়া">
              <Bell  />
              <span data-testid="appbar-unread" style={{ position: 'absolute', top: '2px', right: '2px', minWidth: '18px', height: '18px', padding: '0 4px', background: 'var(--c-error)', color: 'var(--c-on-primary)', borderRadius: 'var(--radius-pill)', fontSize: 'var(--t-caption-size)', lineHeight: '18px', textAlign: 'center' }}>3</span>
            </button>
            <button className="ksr-round" type="button" data-testid="appbar-profile" aria-label="প্রোফাইল">
              <span className="avatar" aria-hidden="true">ম</span>
            </button>
          </div>
        </header>
      
        <main className="ksr-main sf-screen-time" >
      
          
          <section className="ksr-section" aria-labelledby="st-switch-label">
            <p className="ksr-eyebrow" id="st-switch-label">সন্তান নির্বাচন</p>
            <div className="ksr-rail is-square" role="group" aria-label="সন্তান নির্বাচন">
              <button className="ksr-tile is-on" type="button" style={{ font: 'inherit' }} aria-pressed="true" data-testid="st-switch-rafid">
                <span className="media"><CoverFill label="র" /></span>
                <span className="ksr-tile-title">রাফিদ</span>
              </button>
              <button className="ksr-tile" type="button" style={{ font: 'inherit' }} aria-pressed="false" data-testid="st-switch-mahin">
                <span className="media"><CoverFill label="ম" /></span>
                <span className="ksr-tile-title">মাহিন</span>
              </button>
            </div>
          </section>
      
          
          <section className="ksr-hero" data-component="card" aria-labelledby="st-now-label">
            <div className="row">
              <p className="t-body-sm t-semibold ksr-grow" id="st-now-label" data-testid="st-now-label">আজ ব্যবহার হয়েছে</p>
              <span className={blocked ? 'ksr-badge is-warn' : 'ksr-badge is-ok'} data-testid="st-now-status">{statusLabel}</span>
            </div>
            <p className="t-display-lg" style={{ marginTop: 'var(--space-sm)' }} data-testid="st-now-value">{bn(USED_MINUTES)} মিনিট</p>
            <div className="progress" style={{ marginTop: 'var(--space-md)' }} role="progressbar" aria-valuenow={USED_MINUTES} aria-valuemin={0} aria-valuemax={limit} aria-label="আজকের ব্যবহার">
              <div className="progress-fill" style={{ width: `${barPercent}%` }} data-testid="st-now-bar"></div>
            </div>
            <p className="t-caption" style={{ marginTop: 'var(--space-sm)' }} data-testid="st-now-note">
              {limit === 0
                ? 'আজ কোনো সীমা নেই'
                : `দৈনিক সীমা ${bn(limit)} মিনিট · আরও ${bn(remaining)} মিনিট বাকি`}
            </p>
          </section>
      
          
          <section className="ksr-panel" data-component="card" aria-labelledby="st-limit-label">
            <div className="row">
              <p className="t-body-sm t-semibold ksr-grow" id="st-limit-label" data-testid="st-limit-label">দৈনিক সীমা</p>
              <span className="t-body-sm t-bold" data-testid="st-limit-value">{bn(limit)} মিনিট</span>
            </div>
            <input className="input" type="range" min="0" max="240" step="15" value={limit} onChange={(e) => setLimit(Number(e.target.value))} onPointerUp={() => void saveLimit(limit)} onKeyUp={() => void saveLimit(limit)} style={{ marginTop: 'var(--space-md)' }} aria-label="দৈনিক স্ক্রিন টাইম সীমা" data-testid="st-limit-slider" disabled={saving} />
            <div className="st-limit-values-dlv" style={{ marginTop: 'var(--space-xs)' }}>
              <span className="t-caption" data-testid="st-limit-min">০ মিনিট</span>
              <span className="t-caption" data-testid="st-limit-max">২৪০ মিনিট</span>
            </div>
            <div className="row" style={{ flexWrap: 'wrap', marginTop: 'var(--space-sm)' }} role="group" aria-label="দ্রুত সীমা">
              {presets.map((preset) => (
                <button
                  key={preset.testId}
                  className={preset.value === limit ? 'ksr-chip is-on' : 'ksr-chip'}
                  type="button"
                  aria-pressed={preset.value === limit}
                  disabled={saving}
                  onClick={() => void saveLimit(preset.value)}
                  data-testid={preset.testId}
                >
                  {preset.label}
                </button>
              ))}
            </div>
            {notice ? (
              <p className="t-caption" role="status" style={{ marginTop: 'var(--space-sm)' }} data-testid="st-limit-notice">{notice}</p>
            ) : null}
            <p className="t-caption" style={{ marginTop: 'var(--space-sm)' }} data-testid="st-limit-help">
              সীমা শেষ হলে অ্যাপ বন্ধ হয়ে যাবে — শিক্ষার কনটেন্ট ছাড়া কিছুই দেখা যাবে না।
            </p>
          </section>
      
          
          <section className="ksr-panel" data-component="card" aria-labelledby="st-usage-label">
            <p className="t-body-sm t-semibold" id="st-usage-label" data-testid="st-usage-label">গত ৭ দিন</p>
            <div className="chart" style={{ marginTop: 'var(--space-md)' }} data-component="chart" role="img" aria-label="গত ৭ দিনের স্ক্রিন টাইম">
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">৩২</span><span className="bar" style={{ height: '45px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">রবি</span></div>
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">৪৮</span><span className="bar" style={{ height: '67px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">সোম</span></div>
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">৫৬</span><span className="bar" style={{ height: '78px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">মঙ্গল</span></div>
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">৩৮</span><span className="bar" style={{ height: '53px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">বুধ</span></div>
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">৬০</span><span className="bar" style={{ height: '84px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">বৃহঃ</span></div>
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">৪৮</span><span className="bar" style={{ height: '67px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">শুক্র</span></div>
              <div className="chart-col"><span className="t-caption" data-testid="st-week-value">২৪</span><span className="bar" style={{ height: '34px' }} data-testid="st-week-bar"></span><span className="t-caption bar-label" data-testid="st-week-day">আজ</span></div>
            </div>
          </section>
      
          
          <section className="ksr-panel" data-component="card" aria-labelledby="st-ext-label">
            <div className="st-info">
              <Clock4  />
              <div className="ksr-col ksr-grow">
                <p className="t-body-sm t-semibold" id="st-ext-label" data-testid="st-ext-label">অতিরিক্ত সময় দিন</p>
                <p className="t-caption" data-testid="st-ext-body">{extended ? 'আজকের বাড়তি সময় নেওয়া হয়েছে' : '১৫ মিনিট · একবারই দেওয়া যাবে'}</p>
              </div>
            </div>
            <button className="ksr-btn is-quiet is-block" style={{ marginTop: 'var(--space-md)' }} type="button" disabled={extended || saving} onClick={extend} data-testid="st-ext-cta">
              ১৫ মিনিট বাড়াও
            </button>
          </section>
      
          
          <section className="ksr-panel" data-component="card" aria-labelledby="st-blocked-label">
            <div className="st-info">
              <ShieldCheck  />
              <div className="ksr-col ksr-grow">
                <p className="t-body-sm t-semibold" id="st-blocked-label" data-testid="st-blocked-label">ব্লকের অবস্থা</p>
                <p className="t-caption" data-testid="st-blocked-note">
                  {blocked
                    ? `আজ সীমা ${bn(limit)} মিনিট — ${bn(USED_MINUTES)} মিনিট পূর্ণ হয়েছে, তাই সন্তান এখন ব্লক করা আছে।`
                    : `আজ সীমা ${bn(limit)} মিনিট — এখন ${bn(USED_MINUTES)} মিনিট হয়েছে, তাই ব্লক করা নেই। সীমা পূর্ণ হলে সার্ভার থেকেই বন্ধ হয়ে যায় এবং দেখায় — সন্তান এখন ব্লক করা আছে।`}
                </p>
              </div>
            </div>
          </section>
      
        </main>
      
        <nav className="ksr-tabbar" aria-label="প্রধান নেভিগেশন">
          <a className="ksr-tab" href="/parent" data-testid="nav-dashboard">
            <LayoutDashboard  />
            ড্যাশবোর্ড
          </a>
          <a className="ksr-tab" href="/parent/progress" data-testid="nav-progress">
            <TrendingUp  />
            অগ্রগতি
          </a>
          <a className="ksr-tab" href="/parent/screen-time" data-testid="nav-screentime" aria-current="page">
            <Timer  />
            স্ক্রিন টাইম
          </a>
          <a className="ksr-tab" href="/parent/alerts" data-testid="nav-alerts">
            <Bell  />
            অ্যালার্ট
          </a>
          <a className="ksr-tab" href="/parent/settings" data-testid="nav-settings">
            <Settings  />
            সেটিংস
          </a>
        </nav>
    </div>
  );
}
